bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK04_CONTAINER_NOT_RUNNING; exit 61; }
if docker logs --tail 140 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$';then echo STK04_ALREADY_READY=PASS; exit 0;fi
docker exec "$name" node --input-type=module -e '
import {createCreatorPollingRuntime} from "./src/runtime/creatorPollingMain.mjs";
try {
 const rt=await createCreatorPollingRuntime();
 await rt.close();
 console.log("STK04_CREATOR_RUNTIME_CONSTRUCTION_PASS");
 process.exit(0);
} catch (e) {
 const c=String(e?.code??"");
 const m=String(e?.message??"");
 if (c==="28P01")process.exit(80);
 if (c==="3D000")process.exit(81);
 if (c==="42501")process.exit(82);
 if (c==="ECONNREFUSED")process.exit(83);
 if (c==="ENOTFOUND"||c==="EAI_AGAIN")process.exit(84);
 if (c==="ETIMEDOUT"||c==="UND_ERR_CONNECT_TIMEOUT")process.exit(85);
 if (c==="ERR_MODULE_NOT_FOUND")process.exit(86);
 if (c==="ENOENT"||c==="EACCES")process.exit(87);
 if (/VideoBot source module missing owned dependencies|verified GATE owner provider missing/.test(m))process.exit(88);
 if (/CREATOR_POLL_EXISTING_WEBHOOK_MUST_NOT_BE_REPLACED/.test(m))process.exit(89);
 if (/CREATOR_POLL_SCHEMA_INCOMPLETE|VideoBot migration/.test(m))process.exit(90);
 if (/verified bot|identity|CREATOR_BOT|TELEGRAM|HTTP/i.test(m))process.exit(91);
 if (/relation .* does not exist|syntax error|already exists|duplicate|constraint/i.test(m))process.exit(92);
 if (/getMe|401|403|404|429/.test(m))process.exit(93);
 if (/CREATOR_POLL_/.test(m))process.exit(94);
 process.exit(95);
}'
